def F(**kw):
    direction = kw["direction"]
    weight = kw.get("weight", 1.0)
    signed = weight if direction == "FOR" else (-weight if direction == "AGAINST" else 0)
    return {
        "id": kw["id"],
        "article_id": kw.get("article_id"),
        "public_post_id": kw.get("public_post_id"),
        "person_id": kw.get("person_id"),
        "actor": kw["actor"],
        "direction": direction,
        "driver": kw["driver"],
        "quote": kw["quote"],
        "url": kw["url"],
        "published_at": kw["published_at"],
        "published_at_sast": kw["published_at_sast"],
        "fact_label": kw.get("fact_label", "Proven"),
        "steelman_for": kw.get("steelman_for", ""),
        "steelman_against": kw.get("steelman_against", ""),
        "evidence_notes": kw.get("evidence_notes", ""),
        "target_inferred": kw.get("target_inferred", False),
        "target_context_quote": kw.get("target_context_quote"),
        "byline": kw.get("byline", "Newsday"),
        "weight": weight,
        "signed_score": signed,
        "methodology_version": "0.3-draft",
        "coder": "mediawatch-sa-pilot",
        "created_at": NOW,
        "publication_id": "newsday",
        "credit": kw.get("credit"),
        "sample_frame": kw.get("sample_frame", "counter_pull"),
        "accountability_status": kw.get("accountability_status", "bias"),
    }

